});

await t.require(
  queued,
  satisfies(
    (value: unknown) =>
      Array.isArray(value) &&
      ["turn.started", "model.started"].every((type) =>
        (value as QueuedAuditEvent[]).some(
          (entry) => entry.type === type && /^\d+:\d+$/u.test(entry.position),
