    "the audit hook queued the first turn's turn.started and model.started when their export failed",
  ),
);

await t.require(
  tokens,
  satisfies<readonly string[]>(
    (observed) => observed.includes(SERVER_CONTEXT_TOKEN),
    "contains the channel's context token",
  ),
);

await t.require(
  tokens,
  satisfies<readonly string[]>(
    (observed) => !observed.includes(CLIENT_CONTEXT_TOKEN),
    "does not contain the replaced client context token",
  ),
);

await t.require(
  tokens,
  satisfies<readonly string[]>(
    (observed) =>
      observed.filter((token) => token === SECOND_CLIENT_CONTEXT_TOKEN).length === 1,
    "contains the fresh client context token exactly once",
  ),
);

await t.require(
  tokens,
  satisfies<readonly string[]>(
    (observed) => !observed.includes(FIRST_CLIENT_CONTEXT_TOKEN),
    "does not contain the first turn's client context token",
