await t.require(
  unknownThread,
  satisfies(
    (value: ClearResponse) => value.code === "session_not_active",
    "clearing an unknown thread reports session_not_active",
  ),
);

await t.require(
  started,
  satisfies(
    (value: Delivery) => value.ok === true && typeof value.sessionId === "string",
    "the initial message starts a session",
  ),
);

await t.require(
  clearedResponse,
