t.check(deliveryIds.size, equals(groups.flatMap((group) => group.markers).length)).label(
  "each request retains its delivery ID",
);

await t.require(
  initial,
  satisfies(
    (value: Delivery) => value.ok === true && typeof value.sessionId === "string",
    "the initial message starts a session",
