  satisfies(
    (value: OwnerResponse) => value.sessionId === null,
    "/new does not start a replacement model session",
  ),
);

await t.require(
  replacement,
  satisfies(
    (value: Delivery) =>
      value.ok === true &&
      typeof value.sessionId === "string" &&
      value.sessionId !== previousSessionId,
    "the same thread token starts a fresh session after reset",
  ),
);

await t.require(
  started,
  satisfies(
    (value: Delivery) => value.ok === true && typeof value.sessionId === "string",
    "the initial channel message starts a session",
  ),
);

await t.require(
  replacement,
  satisfies(
    (value: Delivery) => value.sessionId === sessionId,
    "the replacement remains in the same durable session",
