await t.require(
  result.events,
  satisfies(
    (events: typeof result.events) =>
      !events.some(
        (event) =>
          (event.type === "content.delta" && event.data.delta.includes("Original")) ||
          (event.type === "content.completed" && String(event.data.value).includes("Original")),
