);

await t.require(
  sent,
  satisfies(
    (value: AcceptedResponse) =>
      typeof value.deliveryId === "string" && value.sessionId === sessionId,
    "the message route sends to the exact session ID",
  ),
);

await t.require(
  cancelled,
  satisfies(
    (value: AcceptedResponse) =>
      typeof value.deliveryId === "string" && value.sessionId === sessionId,
    "cancel targets the exact session ID",
  ),
);

await t.require(
  compacted,
  satisfies(
    (value: AcceptedResponse) =>
      typeof value.deliveryId === "string" && value.sessionId === sessionId,
    "compact targets the exact session ID",
